import { useEffect, useState } from 'react'
import { ArrowRight, Bell, Camera, Check, Clock3, HelpCircle, KeyRound, LogOut, MapPin, Search, Send, Settings, ShieldCheck, ShoppingBag, Sparkles, Star, Store, Truck, UserCircle, Utensils } from 'lucide-react'
import { formatNaira, restaurants, sapeleLocations } from './data'
import { loadOrders } from './services/orderService'

const navigate = (path) => { window.history.pushState({}, '', path); window.dispatchEvent(new PopStateEvent('popstate')) }

function PageFrame({ eyebrow, title, intro, children }) {
  return <main className="route-page"><div className="route-hero"><span className="section-kicker">{eyebrow}</span><h1>{title}</h1><p>{intro}</p></div>{children}</main>
}

function DiscoveryPage({ offers = false }) {
  const [query, setQuery] = useState('')
  const [openOnly, setOpenOnly] = useState(false)
  const [liveRestaurants, setLiveRestaurants] = useState(null)
  useEffect(() => { fetch(`${import.meta.env.VITE_API_BASE_URL || 'http://localhost:4000'}/api/restaurants?limit=24`).then((response) => response.ok ? response.json() : null).then((body) => body?.restaurants && setLiveRestaurants(body.restaurants)).catch(() => undefined) }, [])
  const source = liveRestaurants || restaurants
  const visible = source.filter((restaurant) => (!openOnly || restaurant.openNow !== false) && (!query || `${restaurant.name} ${restaurant.cuisine || restaurant.description || ''} ${(restaurant.items || []).map((item) => item.name).join(' ')}`.toLowerCase().includes(query.toLowerCase())))
  return <PageFrame eyebrow={offers ? 'DOORSTEP DEALS' : 'DISCOVER SAPELE'} title={offers ? 'Good food, better timing.' : 'Find your next favourite.'} intro={offers ? 'Limited-time offers from the local kitchens we love. Every campaign is configured by the DOORSTEP team.' : 'Browse approved restaurants, compare delivery times, and find something worth sharing.'}><section className="discovery-toolbar"><div className="route-search"><Search size={18} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search restaurants or dishes" /></div><label className="filter-check"><input type="checkbox" checked={openOnly} onChange={(event) => setOpenOnly(event.target.checked)} /> Open now</label></section><section className="route-grid">{visible.map((restaurant) => <article className="route-restaurant" key={restaurant.id}><img src={restaurant.image || restaurants[0].image} alt={restaurant.name} /><div><div className="route-restaurant-top"><h2>{restaurant.name}</h2><span><Star size={14} fill="currentColor" /> {restaurant.rating}</span></div><p>{restaurant.cuisine || restaurant.description || 'Local favourites'}</p><small><Clock3 size={13} /> {restaurant.time || `${restaurant.openingTime || '09:00'}–${restaurant.closingTime || '22:00'}`} · {restaurant.fee || 'Delivery calculated at checkout'}</small><button className="text-link" onClick={() => navigate('/restaurants/' + (restaurant.slug || restaurant.name.toLowerCase().replaceAll(' ', '-')))}>View menu <ArrowRight size={15} /></button></div></article>)}</section>{visible.length === 0 && <div className="empty-state">No approved kitchens match that search.</div>}</PageFrame>
}

function LegacyAuthPage({ register = false }) {
  const [role, setRole] = useState('customer')
  const [submitted, setSubmitted] = useState(false)
  if (submitted) return <PageFrame eyebrow="WELCOME TO DOORSTEP" title="You’re on your way." intro="This foundation has captured the entry point. Secure server authentication and verification will replace this local submission in the next backend phase."><div className="submitted-card"><Check size={24} /><h2>{role === 'customer' ? 'Account request received' : `${role} portal selected`}</h2><p>We’ll take you to the correct dashboard after authentication is connected.</p><button className="primary-button" onClick={() => navigate('/')}>Back to home <ArrowRight size={16} /></button></div></PageFrame>
  return <PageFrame eyebrow={register ? 'CREATE YOUR ACCOUNT' : 'WELCOME BACK'} title={register ? 'One account. The right experience.' : 'Come on in.'} intro={register ? 'Choose how you’ll use DOORSTEP. Your role determines the tools and dashboard you see.' : 'Choose your DOORSTEP portal so we can send you to the right place.'}><section className="auth-layout"><div className="role-picker"><button className={role === 'customer' ? 'role-card selected' : 'role-card'} onClick={() => setRole('customer')}><Utensils size={23} /><strong>I’m ordering food</strong><span>Customer account</span></button><button className={role === 'restaurant' ? 'role-card selected' : 'role-card'} onClick={() => setRole('restaurant')}><Store size={23} /><strong>I own a restaurant</strong><span>Restaurant partner</span></button><button className={role === 'rider' ? 'role-card selected' : 'role-card'} onClick={() => setRole('rider')}><Truck size={23} /><strong>I want to deliver</strong><span>Rider account</span></button></div><form className="auth-form" onSubmit={(event) => { event.preventDefault(); setSubmitted(true) }}><h2>{register ? 'Create account' : 'Log in'}</h2>{register && <div className="form-row"><label>First name<input required name="firstName" /></label><label>Last name<input required name="lastName" /></label></div>}<label>Email address<input required type="email" name="email" /></label><label>{register ? 'Phone number' : 'Password'}<input required type={register ? 'tel' : 'password'} name={register ? 'phone' : 'password'} /></label>{register && <label>Password<input required type="password" name="password" /></label>}<label className="terms-check"><input type="checkbox" required /> I agree to the DOORSTEP terms and privacy policy.</label><button className="checkout-button" type="submit">{register ? 'Create account' : 'Continue'} <ArrowRight size={17} /></button><p className="form-footnote">{register ? 'Already have an account? ' : 'New to DOORSTEP? '}<button type="button" onClick={() => navigate(register ? '/login' : '/register')}>{register ? 'Log in' : 'Create an account'}</button></p></form></section></PageFrame>
}

function AuthPage({ register = false, portalRole = 'CUSTOMER' }) {
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const submit = async (event) => {
    event.preventDefault()
    setBusy(true)
    setError('')
    const values = Object.fromEntries(new FormData(event.currentTarget).entries())
    const endpoint = register ? '/api/auth/register' : '/api/auth/login'
    const payload = register ? { ...values, phone: values.phone, verificationId: values.verificationId } : { email: values.email, password: values.password }
    try {
      const response = await fetch(`${import.meta.env.VITE_API_BASE_URL || 'http://localhost:4000'}${endpoint}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) })
      const body = await response.json()
      if (!response.ok) throw new Error(body.error === 'ACCOUNT_ALREADY_EXISTS' ? 'An account with this email already exists.' : body.error === 'INVALID_CREDENTIALS' ? 'Email or password is incorrect.' : body.error || 'Authentication failed.')
      if (body.user.role !== portalRole) throw new Error(`This account is ${body.user.role.toLowerCase()} access, not ${portalRole.toLowerCase()} access.`)
      localStorage.setItem('doorstep-token', body.token)
      const destination = body.user.role === 'RESTAURANT' ? '/restaurant/dashboard' : body.user.role === 'RIDER' ? '/rider/dashboard' : '/account/orders'
      navigate(destination)
    } catch (authError) { setError(authError.message) } finally { setBusy(false) }
  }
  const title = register ? 'Create your customer account' : portalRole === 'CUSTOMER' ? 'Log in to DOORSTEP' : `${portalRole === 'RESTAURANT' ? 'Partner' : 'Rider'} portal login`
  const roleCopy = portalRole === 'CUSTOMER' ? { eyebrow: 'CUSTOMER ACCESS', title: 'Your next good meal starts here.', intro: 'Sign in to continue orders, track deliveries, save favourites, and keep your account details ready.', heading: 'Welcome back', detail: 'Your personal food marketplace for Sapele.' } : portalRole === 'RESTAURANT' ? { eyebrow: 'RESTAURANT OWNER ACCESS', title, intro: 'Sign in to manage your kitchen, menus, paid orders, and restaurant earnings from one protected workspace.', heading: 'Run your kitchen with clarity', detail: 'Orders, menus, and payouts stay connected to your approved restaurant.' } : { eyebrow: 'RIDER ACCESS', title, intro: 'Sign in to manage availability, accept deliveries, update stages, and review your delivery earnings securely.', heading: 'Ready for the next route', detail: 'Your rider workspace keeps each handoff visible and accountable.' }
  return <PageFrame eyebrow={register ? 'CREATE YOUR ACCOUNT' : roleCopy.eyebrow} title={register ? title : roleCopy.title} intro={register ? 'Create a customer account with verified access to ordering, delivery tracking, support, and saved preferences.' : roleCopy.intro}><section className={`auth-layout auth-layout-${portalRole.toLowerCase()}`}><div className="partner-cta"><ShieldCheck size={25} /><span className="section-kicker">{portalRole === 'CUSTOMER' ? 'DOORSTEP CUSTOMER' : portalRole === 'RESTAURANT' ? 'APPROVED PARTNER WORKSPACE' : 'APPROVED RIDER WORKSPACE'}</span><h2>{roleCopy.heading}</h2><p>{roleCopy.detail}</p><div className="auth-trust-points"><span><Check size={13} /> Secure sessions</span><span><Check size={13} /> Role-checked access</span><span><Check size={13} /> Support when needed</span></div></div><form className="auth-form" onSubmit={submit}><h2>{register ? 'Customer account' : 'Sign in securely'}</h2>{register && <div className="form-row"><label>First name<input required name="firstName" /></label><label>Last name<input required name="lastName" /></label></div>}<label>Email address<input required type="email" name="email" autoComplete="email" /></label>{register && <label>Phone number<input required type="tel" name="phone" /></label>}<label>Password<input required minLength="8" type="password" name="password" autoComplete={register ? 'new-password' : 'current-password'} /></label>{register && <label className="terms-check"><input type="checkbox" required /> I agree to the DOORSTEP terms and privacy policy.</label>}{error && <div className="admin-login-error">{error}</div>}<button className="checkout-button" disabled={busy} type="submit">{busy ? 'Please wait...' : register ? 'Create account' : `Continue to ${portalRole === 'CUSTOMER' ? 'DOORSTEP' : portalRole === 'RESTAURANT' ? 'owner workspace' : 'rider workspace'}`} <ArrowRight size={17} /></button><p className="form-footnote">{register ? 'Already have an account? ' : 'Need an account? '}<button type="button" onClick={() => navigate(register ? '/login' : '/register')}>{register ? 'Log in' : 'Register'}</button></p></form></section></PageFrame>
}

function RegistrationPage() {
  const [role, setRole] = useState('customer')
  return <PageFrame eyebrow="JOIN DOORSTEP" title="Choose your DOORSTEP account." intro="Each role has its own onboarding, verification, and dashboard. Choose the experience that fits you."><section className="registration-choice"><button className={role === 'customer' ? 'role-card selected' : 'role-card'} onClick={() => setRole('customer')}><Utensils size={25} /><strong>I’m ordering food</strong><span>Customer account with email or phone verification.</span></button><button className={role === 'restaurant' ? 'role-card selected' : 'role-card'} onClick={() => setRole('restaurant')}><Store size={25} /><strong>I own a restaurant</strong><span>Business, owner identity, and document verification.</span></button><button className={role === 'rider' ? 'role-card selected' : 'role-card'} onClick={() => setRole('rider')}><Truck size={25} /><strong>I want to deliver</strong><span>Identity, vehicle, emergency contact, and rider verification.</span></button>{role === 'customer' ? <VerifiedCustomerRegistration /> : <div className="registration-action"><h2>{role === 'restaurant' ? 'Restaurant partner onboarding' : 'Rider onboarding'}</h2><p>Continue to the dedicated {role} application. It will remain pending until DOORSTEP approval.</p><button className="checkout-button" onClick={() => navigate(role === 'restaurant' ? '/partners/restaurants/register' : '/riders/register')}>Continue to {role === 'restaurant' ? 'restaurant signup' : 'rider signup'} <ArrowRight size={17} /></button></div>}</section></PageFrame>
}

function VerifiedCustomerRegistration() {
  const [step, setStep] = useState('details')
  const [challenge, setChallenge] = useState(null)
  const [destination, setDestination] = useState('')
  const [registration, setRegistration] = useState(null)
  const [error, setError] = useState('')
  const requestCode = async (event) => {
    event.preventDefault(); setError('')
    const form = new FormData(event.currentTarget); const email = form.get('email'); setDestination(email); setRegistration(Object.fromEntries(form.entries()))
    const response = await fetch(`${import.meta.env.VITE_API_BASE_URL || 'http://localhost:4000'}/api/auth/verification/request`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ destination: email, channel: 'email' }) })
    const body = await response.json(); if (!response.ok) return setError(body.error || 'Could not send verification code.')
    setChallenge(body); setStep('verify')
  }
  if (step === 'verify') return <form className="auth-form verification-card" onSubmit={async (event) => { event.preventDefault(); const code = new FormData(event.currentTarget).get('code'); const response = await fetch(`${import.meta.env.VITE_API_BASE_URL || 'http://localhost:4000'}/api/auth/verification/verify`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ challengeId: challenge.challengeId, destination, code }) }); const body = await response.json(); if (!body.verified) return setError('That code is invalid or expired.'); const registerResponse = await fetch(`${import.meta.env.VITE_API_BASE_URL || 'http://localhost:4000'}/api/auth/register`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...registration, verificationId: challenge.challengeId }) }); const registered = await registerResponse.json(); if (!registerResponse.ok) return setError(registered.error || 'Could not create account.'); localStorage.setItem('doorstep-token', registered.token); navigate('/account') }}><span className="section-kicker">CHECK YOUR EMAIL</span><h2>Enter your 6-digit code.</h2><p>We sent a verification code to {destination}. Development mode shows the code in the API terminal.</p><label>Verification code<input required name="code" inputMode="numeric" pattern="[0-9]{6}" maxLength="6" /></label>{error && <div className="admin-login-error">{error}</div>}<button className="checkout-button" type="submit">Verify and create account <Check size={17} /></button></form>
  return <form className="auth-form customer-register-card" onSubmit={requestCode}><span className="section-kicker">CUSTOMER ACCOUNT</span><h2>Create your account.</h2><div className="form-row"><label>First name<input required name="firstName" /></label><label>Last name<input required name="lastName" /></label></div><label>Email address<input required type="email" name="email" /></label><label>Phone number<input required type="tel" name="phone" /></label><label>Password<input required minLength="8" type="password" name="password" /></label>{error && <div className="admin-login-error">{error}</div>}<button className="checkout-button" type="submit">Send verification code <ArrowRight size={17} /></button></form>
}

function AccountDashboard() {
  const [user, setUser] = useState(null)
  const [orders, setOrders] = useState(() => loadOrders())
  const recentOrders = orders.slice(0, 2)
  useEffect(() => { const token = localStorage.getItem('doorstep-token'); if (!token) return; const headers = { Authorization: `Bearer ${token}` }; fetch(`${import.meta.env.VITE_API_BASE_URL || 'http://localhost:4000'}/api/auth/me`, { headers }).then((response) => response.json()).then((body) => setUser(body.user)).catch(() => undefined); fetch(`${import.meta.env.VITE_API_BASE_URL || 'http://localhost:4000'}/api/orders`, { headers }).then((response) => response.ok ? response.json() : null).then((body) => body?.orders && setOrders(body.orders)).catch(() => undefined) }, [])
  return <PageFrame eyebrow="YOUR DOORSTEP" title={user ? `Good to see you, ${user.firstName}.` : 'Your account dashboard.'} intro="Your orders, saved details, and support tools in one calm place."><section className="account-dashboard"><div className="account-profile-card"><div className="profile-icon"><UserCircle size={39} /></div><div><span className="section-kicker">CUSTOMER PROFILE</span><h2>{user ? `${user.firstName} ${user.lastName}` : 'Loading profile...'}</h2><p>{user?.email || 'Authenticated DOORSTEP customer'}</p></div><button className="quiet-button">Edit profile</button></div><div className="account-welcome-band"><div><span className="section-kicker">YOUR NEXT BITE</span><h2>Something lovely is close.</h2><p>Three local kitchens are open and ready around Amukpe.</p><button className="primary-button" onClick={() => navigate('/restaurants')}>Explore restaurants <ArrowRight size={16} /></button></div><div className="account-food-orbit"><span>🍚</span><span>🍗</span><span>🥤</span></div></div><div className="account-confidence-row"><div><span className="confidence-number">0</span><div><strong>Active deliveries</strong><small>Nothing to chase right now</small></div></div><div><span className="confidence-number">1</span><div><strong>Saved location</strong><small>Amukpe, Sapele</small></div></div><div><span className="confidence-number">∞</span><div><strong>Good choices</strong><small>Always worth discovering</small></div></div></div><div className="account-active-order"><div className="active-order-icon"><Clock3 size={22} /></div><div><span className="section-kicker">ORDER AT A GLANCE</span><h3>{recentOrders.length ? 'Your latest order is close at hand.' : 'Ready when you are'}</h3><p>{recentOrders.length ? `${recentOrders[0].restaurantName} · ${recentOrders[0].status.replaceAll('_', ' ')}` : 'No active delivery right now. Your next order will appear here with live kitchen and rider updates.'}</p></div><button className="text-link" onClick={() => navigate(recentOrders.length ? '/account/orders' : '/restaurants')}>{recentOrders.length ? 'View orders' : 'Find food'} <ArrowRight size={15} /></button></div>{recentOrders.length > 0 && <div className="account-recent"><div className="account-discover-row"><div><span className="section-kicker">RECENTLY ORDERED</span><h2>Good enough to repeat.</h2></div><button className="text-link" onClick={() => navigate('/account/orders')}>All orders <ArrowRight size={15} /></button></div>{recentOrders.map((recentOrder) => <div className="recent-order-row" key={recentOrder.id}><div className="recent-order-mark"><ShoppingBag size={17} /></div><div><strong>{recentOrder.restaurantName}</strong><small>{recentOrder.items.map((item) => `${item.quantity}× ${item.name}`).join(', ')}</small></div><button className="add-button" onClick={() => navigate('/restaurants')}>Order again</button></div>)}</div>}<div className="account-dashboard-grid"><button onClick={() => navigate('/account/orders')}><PackageIcon /><strong>Orders</strong><span>Track and reorder food</span></button><button><MapPin size={24} /><strong>Addresses</strong><span>Save delivery locations</span></button><button><HeartIcon /><strong>Favorites</strong><span>Your go-to kitchens</span></button><button onClick={() => navigate('/help')}><HelpCircle size={24} /><strong>Support</strong><span>Get help with an order</span></button></div><div className="account-discover-row"><div><span className="section-kicker">DISCOVER SAPELE</span><h2>Choose your mood.</h2></div><button className="text-link" onClick={() => navigate('/offers')}>See offers <ArrowRight size={15} /></button></div><div className="mood-grid"><button onClick={() => navigate('/restaurants')}><span>🍚</span><strong>Comfort food</strong><small>Warm, familiar, local</small></button><button onClick={() => navigate('/restaurants')}><span>🔥</span><strong>Something bold</strong><small>Grills, suya and spice</small></button><button onClick={() => navigate('/offers')}><span>✦</span><strong>Good deal</strong><small>Make tonight go further</small></button></div></section></PageFrame>
}

function PackageIcon() { return <ShoppingBag size={24} /> }
function HeartIcon() { return <span className="account-heart">♡</span> }

const apiBase = import.meta.env.VITE_API_BASE_URL || 'http://localhost:4000'
const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('doorstep-token')}`, 'Content-Type': 'application/json' })
export function SignOutButton() { const [open, setOpen] = useState(false); const signOut = async () => { await fetch(`${apiBase}/api/auth/logout`, { method: 'POST', headers: authHeaders() }).catch(() => undefined); localStorage.removeItem('doorstep-token'); navigate('/') }; return <span className="sign-out-menu"><button className="sign-out-button" type="button" aria-label="Open sign-out options" title="Open sign-out options" onClick={() => setOpen(!open)}><span className="sign-out-icon"><LogOut size={15} /></span><ArrowRight size={14} /></button>{open && <button className="sign-out-confirm" type="button" onClick={signOut}>Sign out</button>}</span> }

function ProfilePage() {
  const [user, setUser] = useState(null)
  const [message, setMessage] = useState('')
  const [form, setForm] = useState({ firstName: '', lastName: '', phone: '', preferredName: '', dateOfBirth: '', dietaryPreference: '', deliveryNotes: '' })
  const [saving, setSaving] = useState(false)
  const [photoBusy, setPhotoBusy] = useState(false)
  useEffect(() => { fetch(`${apiBase}/api/auth/me`, { headers: authHeaders() }).then((response) => response.json()).then((body) => { setUser(body.user); setForm({ firstName: body.user.firstName || '', lastName: body.user.lastName || '', phone: body.user.phone || '', preferredName: body.user.preferredName || '', dateOfBirth: body.user.dateOfBirth ? body.user.dateOfBirth.slice(0, 10) : '', dietaryPreference: body.user.dietaryPreference || '', deliveryNotes: body.user.deliveryNotes || '' }) }).catch(() => setMessage('Could not load your profile.')) }, [])
  const updateField = (event) => setForm((current) => ({ ...current, [event.target.name]: event.target.value }))
  const saveProfile = async (event) => { event.preventDefault(); setSaving(true); setMessage(''); const response = await fetch(`${apiBase}/api/auth/me`, { method: 'PATCH', headers: authHeaders(), body: JSON.stringify(form) }); const body = await response.json(); setSaving(false); setMessage(response.ok ? 'Your profile details have been saved.' : body.error === 'PHONE_ALREADY_IN_USE' ? 'That phone number is already linked to another account.' : body.error || 'Could not save your profile.'); if (response.ok) setUser(body.user) }
    const uploadPhoto = async (event) => { const file = event.target.files?.[0]; const token = localStorage.getItem('doorstep-token'); if (!file || !token) return; setPhotoBusy(true); setMessage(''); const uploadData = new FormData(); uploadData.append('document', file); const uploadResponse = await fetch(`${apiBase}/api/uploads/private-document`, { method: 'POST', headers: { Authorization: `Bearer ${token}` }, body: uploadData }); const uploadBody = await uploadResponse.json(); if (!uploadResponse.ok) { setPhotoBusy(false); setMessage(uploadBody.error || 'Could not upload your profile photo.'); return } const profileResponse = await fetch(`${apiBase}/api/profile/photo`, { method: 'POST', headers: authHeaders(), body: JSON.stringify({ storageKey: uploadBody.storageKey }) }); const profileBody = await profileResponse.json(); setPhotoBusy(false); setMessage(profileResponse.ok ? 'Your profile photo has been saved.' : profileBody.error || 'Could not save your profile photo.'); if (profileResponse.ok) setUser(profileBody.user) }
    useEffect(() => { const formElement = document.querySelector('.profile-edit-form'); if (!formElement || formElement.querySelector('.profile-extra-fields')) return undefined; const section = document.createElement('div'); section.className = 'profile-extra-fields'; section.innerHTML = '<div class="form-row"><label>Preferred name<input name="preferredName" placeholder="What should we call you?"></label><label>Date of birth<input type="date" name="dateOfBirth"></label></div><label>Dietary preference<select name="dietaryPreference"><option value="">No preference selected</option><option>No pork</option><option>Vegetarian</option><option>Vegan</option><option>Halal</option><option>Low spice</option></select></label><label>General delivery notes<textarea name="deliveryNotes" rows="3" placeholder="Helpful context for future deliveries, such as a preferred landmark."></textarea></label>'; const phone = formElement.querySelector('input[name="phone"]'); phone?.closest('label')?.after(section); const values = { preferredName: form.preferredName, dateOfBirth: form.dateOfBirth, dietaryPreference: form.dietaryPreference, deliveryNotes: form.deliveryNotes }; Object.entries(values).forEach(([name, value]) => { const field = section.querySelector(`[name="${name}"]`); if (field) field.value = value || ''; field?.addEventListener('input', (event) => setForm((current) => ({ ...current, [name]: event.target.value }))) }); const syncFields = () => { Object.keys(values).forEach((name) => { let hidden = formElement.querySelector(`input[type="hidden"][name="${name}"]`); if (!hidden) { hidden = document.createElement('input'); hidden.type = 'hidden'; hidden.name = name; formElement.append(hidden) } hidden.value = section.querySelector(`[name="${name}"]`)?.value || '' }) }; formElement.addEventListener('submit', syncFields, true); return () => formElement.removeEventListener('submit', syncFields, true) }, [user])
  if (!user) return <PageFrame eyebrow="PROFILE" title="Your details" intro={message || 'Loading your profile...'}><div className="submitted-card"><Clock3 size={24} /></div></PageFrame>
  const completion = [form.firstName, form.lastName, user.email, form.phone, form.preferredName, form.dietaryPreference, form.deliveryNotes].filter(Boolean).length * 14
  return <PageFrame eyebrow="PROFILE & SECURITY" title="Keep your details current." intro="Update your personal details whenever you need to. Your changes are saved securely to your DOORSTEP account."><section className="profile-account-layout"><div><form className="profile-edit-form" onSubmit={saveProfile}><div className="profile-edit-header"><label className="profile-photo-picker"><div className="profile-icon">{user.profileImageKey ? <Camera size={30} /> : <UserCircle size={39} />}</div><input type="file" accept="image/jpeg,image/png" onChange={uploadPhoto} disabled={photoBusy} /><span>{photoBusy ? 'Saving photo...' : 'Change photo'}</span></label><div><span className="section-kicker">CUSTOMER ACCOUNT</span><h2>{user.firstName} {user.lastName}</h2><p>{user.email}</p><small className="profile-verified"><Check size={12} /> Account active</small></div></div><div className="profile-completion"><div><strong>Profile completeness</strong><span>{completion}%</span></div><div className="profile-progress"><i style={{ width: `${completion}%` }} /></div></div><div className="form-row"><label>First name<input required name="firstName" value={form.firstName} onChange={updateField} /></label><label>Last name<input required name="lastName" value={form.lastName} onChange={updateField} /></label></div><label>Email address<input disabled value={user.email} readOnly /></label><label>Phone number<input name="phone" value={form.phone} onChange={updateField} placeholder="080 0000 0000" /></label>{message && <div className="profile-message">{message}</div>}<div className="profile-form-actions"><button className="checkout-button" type="submit" disabled={saving}>{saving ? 'Saving changes...' : 'Save changes'} <Check size={17} /></button><button className="quiet-button" type="button" onClick={() => setForm({ firstName: user.firstName || '', lastName: user.lastName || '', phone: user.phone || '' })}>Discard edits</button></div></form><div className="profile-security-grid"><div><ShieldCheck size={21} /><strong>Secure session</strong><small>Your account uses a revocable server session.</small><button className="quiet-button" onClick={() => navigate('/forgot-password')}>Reset password <KeyRound size={13} /></button></div><div><MapPin size={21} /><strong>Saved delivery places</strong><small>Keep addresses and landmarks ready for faster checkout.</small><button className="quiet-button" onClick={() => navigate('/account/addresses')}>Manage addresses <ArrowRight size={13} /></button></div></div></div><aside className="profile-account-menu"><span className="section-kicker">ACCOUNT CENTRE</span><h2>Everything in one place.</h2><button onClick={() => navigate('/account/addresses')}><MapPin size={18} /><span><strong>Addresses</strong><small>Home, work, and delivery notes</small></span><ArrowRight size={14} /></button><button onClick={() => navigate('/account/favorites')}><Star size={18} /><span><strong>Favorites</strong><small>Your saved kitchens and dishes</small></span><ArrowRight size={14} /></button><button onClick={() => navigate('/account/notifications')}><Bell size={18} /><span><strong>Notifications</strong><small>Order and account updates</small></span><ArrowRight size={14} /></button><button onClick={() => navigate('/account/support')}><HelpCircle size={18} /><span><strong>Support centre</strong><small>Get help from DOORSTEP</small></span><ArrowRight size={14} /></button><button onClick={() => navigate('/forgot-password')}><Settings size={18} /><span><strong>Security settings</strong><small>Manage your password access</small></span><ArrowRight size={14} /></button></aside></section></PageFrame>
}

function AddressesPage() {
  const [addresses, setAddresses] = useState([]); const [message, setMessage] = useState(''); const [coords, setCoords] = useState({})
  const load = () => fetch(`${apiBase}/api/addresses`, { headers: authHeaders() }).then((response) => response.json()).then((body) => setAddresses(body.addresses || []))
  useEffect(() => { load(); if (new URLSearchParams(window.location.search).get('locate')) locate() }, [])
  const locate = () => navigator.geolocation?.getCurrentPosition((position) => { setCoords({ latitude: position.coords.latitude, longitude: position.coords.longitude }); setMessage('Location captured. Add a label and address, then save it.') }, () => setMessage('Location permission was not granted. You can still enter the address manually.'))
  const save = async (event) => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); const response = await fetch(`${apiBase}/api/addresses`, { method: 'POST', headers: authHeaders(), body: JSON.stringify({ ...values, addressLine: `${values.area}, ${values.addressLine}`, latitude: coords.latitude, longitude: coords.longitude }) }); setMessage(response.ok ? 'Delivery location saved.' : 'Could not save this address.'); if (response.ok) { event.currentTarget.reset(); load() } }
  return <PageFrame eyebrow="DELIVERY LOCATIONS" title="Save the places life happens." intro="Choose a Sapele area, then add the exact street, house number, and landmark for reliable delivery."><section className="address-page"><div className="address-actions"><button className="primary-button" onClick={locate}><MapPin size={16} /> Use current device location</button>{message && <span>{message}</span>}</div><form className="address-form" onSubmit={save}><span className="section-kicker">NEW SAVED PLACE · SAPELE</span><div className="form-row"><label>Label<input required name="label" placeholder="Home, work, school..." /></label><label>Area<select required name="area" defaultValue=""><option value="" disabled>Select a Sapele area</option>{sapeleLocations.map((location) => <option key={location} value={location}>{location}</option>)}</select></label></div><label>Street, house number, or address<input required name="addressLine" placeholder="Exact street and house number" /></label><label>Landmark or delivery note<input name="landmark" placeholder="Near the pharmacy, beside the junction..." /></label><button className="checkout-button" type="submit">Save delivery location <Check size={17} /></button></form><div className="location-directory"><span className="section-kicker">DELIVERY DIRECTORY</span><h2>Sapele areas</h2><p>Area suggestions are configurable by DOORSTEP operations as delivery coverage grows.</p><div>{sapeleLocations.slice(0, 12).map((location) => <span key={location}>{location}</span>)}</div></div><div className="address-list">{addresses.length === 0 ? <div className="empty-state">No saved locations yet.</div> : addresses.map((address) => <div className="address-card" key={address.id}><MapPin size={19} /><div><strong>{address.label}</strong><p>{address.addressLine}</p><small>{address.landmark || 'No landmark added'}</small></div><button className="quiet-button" onClick={() => fetch(`${apiBase}/api/addresses/${address.id}`, { method: 'DELETE', headers: authHeaders() }).then(load)}>Remove</button></div>)}</div></section></PageFrame>
}

function LocationPage() { const [location, setLocation] = useState(localStorage.getItem('doorstep-location') || 'Amukpe, Sapele'); const [message, setMessage] = useState(''); const saveLocation = (value) => { localStorage.setItem('doorstep-location', value); window.dispatchEvent(new Event('doorstep-location-change')); setLocation(value); setMessage(`Delivering to ${value}`) }; const useLive = () => navigator.geolocation?.getCurrentPosition((position) => saveLocation(`Current device · ${position.coords.latitude.toFixed(4)}, ${position.coords.longitude.toFixed(4)}`), () => setMessage('Location permission was not granted. Choose a Sapele area instead.')); return <PageFrame eyebrow="DELIVERY LOCATION" title="Where should we meet you?" intro="Choose a Sapele area, use your current device location, or save an exact address with a landmark."><section className="location-page"><div className="location-current"><MapPin size={22} /><div><span className="section-kicker">CURRENT DELIVERY LOCATION</span><h2>{location}</h2><p>{message || 'Used for restaurant discovery, delivery estimates, and checkout.'}</p></div></div><button className="primary-button live-location-button" onClick={useLive}><MapPin size={17} /> Use current device location</button><div className="location-directory"><span className="section-kicker">SAPELE DELIVERY AREAS</span><h2>Choose your area</h2><p>Coverage is configured by DOORSTEP operations and can expand as the service grows.</p><div>{sapeleLocations.map((area) => <button key={area} onClick={() => saveLocation(`${area}, Sapele`)}>{area}</button>)}</div></div><button className="checkout-button" onClick={() => navigate('/account/addresses')}>Manage exact addresses <ArrowRight size={17} /></button></section></PageFrame> }

function FavoritesPage() { const [favorites, setFavorites] = useState([]); useEffect(() => { fetch(`${apiBase}/api/favorites`, { headers: authHeaders() }).then((response) => response.json()).then((body) => setFavorites(body.favorites || [])) }, []); return <PageFrame eyebrow="YOUR FAVORITES" title="Keep the good stuff close." intro="Save restaurants and dishes you want to find again when hunger has no patience."><section className="favorites-page">{favorites.length === 0 ? <div className="notification-empty"><HeartIcon /><h2>Your favorites are waiting.</h2><p>Tap the heart on a restaurant or food item to build your personal Sapele shortlist.</p><button className="primary-button" onClick={() => navigate('/restaurants')}>Discover restaurants <ArrowRight size={16} /></button></div> : <div className="favorite-grid">{favorites.map((favorite) => <article className="favorite-card" key={favorite.id}><div className="favorite-image" /><div><span className="section-kicker">{favorite.restaurant ? 'RESTAURANT' : 'FOOD'}</span><h2>{favorite.restaurant?.name || favorite.menuItem?.name}</h2><p>{favorite.restaurant?.description || favorite.menuItem?.description || 'Saved for your next order.'}</p></div></article>)}</div>}</section></PageFrame> }

function NotificationsPage() {
  const [notifications, setNotifications] = useState([])
  const [loading, setLoading] = useState(true)
  const load = () => fetch(`${apiBase}/api/notifications`, { headers: authHeaders() }).then((response) => response.json()).then((body) => setNotifications(body.notifications || [])).finally(() => setLoading(false))
  useEffect(() => { load() }, [])
  const markAll = async () => { await fetch(`${apiBase}/api/notifications/read-all`, { method: 'POST', headers: authHeaders() }); load() }
  const markOne = async (id) => { await fetch(`${apiBase}/api/notifications/${id}/read`, { method: 'PATCH', headers: authHeaders() }); load() }
  return <PageFrame eyebrow="NOTIFICATION CENTER" title="Stay close to every update." intro="Order, payment, delivery, promotion, account, and security updates live here."><section className="notification-page"><div className="notification-toolbar"><div><span className="section-kicker">INBOX</span><h2>{notifications.filter((item) => !item.readAt).length} unread updates</h2></div><button className="text-link" onClick={markAll}>Mark all as read <Check size={15} /></button></div>{loading ? <div className="empty-state">Loading your notifications...</div> : notifications.length === 0 ? <div className="notification-empty"><Bell size={30} /><h2>Your inbox is calm.</h2><p>Payment confirmations, rider updates, and support replies will appear here.</p></div> : <div className="notification-list">{notifications.map((notification) => <button className={notification.readAt ? 'notification-row read' : 'notification-row'} key={notification.id} onClick={() => markOne(notification.id)}><span className="notification-type"><Bell size={16} /></span><div><strong>{notification.title}</strong><p>{notification.body}</p><small>{new Date(notification.createdAt).toLocaleString('en-NG')}</small></div>{!notification.readAt && <i />}</button>)}</div>}</section></PageFrame>
}

function SupportPage() {
  const [tickets, setTickets] = useState([])
  const [submitted, setSubmitted] = useState(false)
  const load = () => fetch(`${apiBase}/api/support/tickets`, { headers: authHeaders() }).then((response) => response.json()).then((body) => setTickets(body.tickets || []))
  useEffect(() => { load() }, [])
  useEffect(() => { const category = new URLSearchParams(window.location.search).get('category'); if (category) { const field = document.querySelector('.support-form select[name="category"]'); if (field) field.value = category } }, [])
  return <PageFrame eyebrow="CUSTOMER SUPPORT" title="Help that follows through." intro="Tell us what happened, include the order context, and keep the ticket number for follow-up."><section className="support-page"><div className="support-layout"><form className="support-form" onSubmit={async (event) => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); const response = await fetch(`${apiBase}/api/support/tickets`, { method: 'POST', headers: authHeaders(), body: JSON.stringify(values) }); if (response.ok) { setSubmitted(true); event.currentTarget.reset(); load() } }}><span className="section-kicker">START A CONVERSATION</span><h2>What do you need help with?</h2><label>Category<select required name="category" defaultValue="PAYMENT"><option value="PAYMENT">Payment problem</option><option value="MISSING_ORDER">Missing order</option><option value="WRONG_FOOD">Wrong food</option><option value="LATE_DELIVERY">Late delivery</option><option value="RESTAURANT">Restaurant problem</option><option value="RIDER">Rider problem</option><option value="ACCOUNT">Account problem</option><option value="REFUND">Refund request</option><option value="TECHNICAL">Technical issue</option></select></label><label>Describe the issue<textarea required minLength="10" name="description" rows="6" placeholder="Tell us what happened, what you expected, and any order number involved." /></label>{submitted && <div className="profile-message">Ticket submitted. Support will respond in the ticket thread.</div>}<button className="checkout-button" type="submit">Submit support ticket <Send size={17} /></button></form><div className="support-guidance"><span className="section-kicker">HOW WE HELP</span><h2>A clear path when dinner goes sideways.</h2><div><strong>Payments</strong><small>We can trace references, pending states, and failed attempts.</small></div><div><strong>Delivery</strong><small>We can review restaurant, rider, timeline, and location events.</small></div><div><strong>Account</strong><small>We can help with access, verification, and profile concerns.</small></div></div></div><div className="ticket-history"><div className="notification-toolbar"><div><span className="section-kicker">YOUR TICKETS</span><h2>Support history</h2></div></div>{tickets.length === 0 ? <div className="empty-state">No support tickets yet.</div> : tickets.map((ticket) => <div className="ticket-row" key={ticket.id}><div><strong>{ticket.ticketNumber}</strong><small>{ticket.category.replaceAll('_', ' ')} · {new Date(ticket.createdAt).toLocaleDateString('en-NG')}</small></div><span className="order-status">{ticket.status}</span></div>)}</div></section></PageFrame>
}

function ConnectedPartnerApplication() {
  const [submitted, setSubmitted] = useState(false)
  const [error, setError] = useState('')
  const submit = async (event) => { event.preventDefault(); setError(''); const response = await fetch(`${apiBase}/api/partner-applications/multipart`, { method: 'POST', body: new FormData(event.currentTarget) }); const body = await response.json(); if (!response.ok) return setError(body.error || 'Could not submit the restaurant application.'); setSubmitted(true) }
  if (submitted) return <PageFrame eyebrow="RESTAURANT PARTNER APPLICATION" title="Application received." intro="Your restaurant account is pending DOORSTEP review. It will remain hidden from customers until approval."><div className="submitted-card"><Check size={24} /><h2>Pending approval</h2><p>Keep your partner details ready. DOORSTEP operations will review the business and identity documents.</p><button className="primary-button" onClick={() => navigate('/')}>Back to home <ArrowRight size={16} /></button></div></PageFrame>
  return <PageFrame eyebrow="RESTAURANT PARTNER APPLICATION" title="Bring your kitchen to more tables." intro="Submit the business, owner, and private verification details required for approval."><form className="application-form" onSubmit={submit}><div className="form-row"><label>Restaurant name<input required name="restaurantName" /></label><label>Business type<select name="businessType" defaultValue="restaurant"><option value="restaurant">Restaurant</option><option value="cafe">Cafe</option><option value="bakery">Bakery</option></select></label></div><label>Registration number<input required name="registrationNumber" /></label><div className="form-row"><label>Business phone<input required name="businessPhone" inputMode="tel" /></label><label>Business email<input required name="businessEmail" type="email" /></label></div><label>Address<input required name="address" /></label><input type="hidden" name="cityName" value="Sapele" /><label>Owner full name<input required name="ownerName" /></label><div className="form-row"><label>Identity type<select required name="ownerIdentityType" defaultValue="national-id"><option value="national-id">National ID</option><option value="drivers-license">Driver’s licence</option><option value="passport">Passport</option></select></label><label>Identity number<input required name="ownerIdentityNumber" /></label></div><div className="form-row"><label>Owner identity document<input required name="documents" type="file" accept="image/jpeg,image/png,.pdf" /></label><label>Business document<input required name="documents" type="file" accept="image/jpeg,image/png,.pdf" /></label></div><label>Partner password<input required name="password" type="password" minLength="8" /></label>{error && <div className="admin-login-error">{error}</div>}<button className="checkout-button" type="submit">Submit application <ArrowRight size={17} /></button></form></PageFrame>
}

